// Normalise the three entry points into one run config
const input = $input.first().json;
const scenarioId = input.scenario_id ? String(input.scenario_id) : null;
// Guardrail on input: scenario IDs become file paths, so allow a strict pattern only
if (scenarioId && !/^s[0-9]{2}_[a-z0-9_]{1,40}$/.test(scenarioId)) {
  throw new Error(`Invalid scenario_id: ${scenarioId}`);
}
// Only two config files exist; anything else is refused
const guardrailsFile = input.guardrails_file || 'guardrails.json';
if (!['guardrails.json', 'guardrails.test.json'].includes(guardrailsFile)) {
  throw new Error(`Invalid guardrails_file: ${guardrailsFile}`);
}
const lisbon = $now.setZone('Europe/Lisbon');
return [{ json: {
  workflow_version: 'v0.4-hitl-logging',
  n8n_execution_id: $execution.id,
  run_started_at: new Date().toISOString(),
  trigger: $('Every day 21:00').isExecuted ? 'schedule' : 'manual',
  mode: scenarioId ? 'scenario' : 'live',
  scenario_id: scenarioId,
  guardrails_file: guardrailsFile,
  today: lisbon.toISODate(),
  target_date: lisbon.plus({ days: 1 }).toISODate(),
} }];

// intervals.icu returns arrays, which n8n splits into items: gather them back
const cfg = $('Run config').first().json;
const rows = (node) => $(node).all().map((i) => i.json).filter((j) => j && j.id);
return [{ json: {
  ...cfg,
  wellness: rows('intervals.icu wellness'),
  activities: rows('intervals.icu activities'),
  weather: $('Open-Meteo forecast').first().json,
} }];

// A scenario file replaces the three API responses; everything downstream is identical
const cfg = $('Run config').first().json;
const s = $input.first().json.data;
return [{ json: {
  ...cfg,
  target_date: s.target_date,
  wellness: s.wellness,
  activities: s.activities,
  weather: s.weather,
} }];

// Builds the "daily context": the only data the maker agent ever sees.
// Pure function, so live API data and sample scenarios go through the same code.
// Data minimisation: numbers and categories only. No names, activity titles,
// GPS, device IDs or timestamps beyond the date.

function buildContext({ targetDate, source, scenarioId, wellness, activities, weather, plan }) {
  const addDays = (iso, n) => {
    const d = new Date(iso + 'T12:00:00Z');
    d.setUTCDate(d.getUTCDate() + n);
    return d.toISOString().slice(0, 10);
  };
  const isNum = (v) => typeof v === 'number' && Number.isFinite(v) && v !== 0;
  const round = (v, dp = 1) => (v == null ? null : Math.round(v * 10 ** dp) / 10 ** dp);
  const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);

  // "today" is the day the workflow runs (the evening before targetDate)
  const today = addDays(targetDate, -1);
  const byDate = Object.fromEntries((wellness || []).map((r) => [r.id, r]));
  const todayRow = byDate[today] || {};
  const prior7 = [1, 2, 3, 4, 5, 6, 7].map((i) => byDate[addDays(today, -i)]).filter(Boolean);

  // --- Recovery: today vs own 7-day baseline (baseline excludes today)
  const hrvBase = mean(prior7.map((r) => r.hrv).filter(isNum));
  const rhrBase = mean(prior7.map((r) => r.restingHR).filter(isNum));
  const hrv = isNum(todayRow.hrv) ? todayRow.hrv : null;
  const rhr = isNum(todayRow.restingHR) ? todayRow.restingHR : null;
  const recovery = {
    hrv_ms: hrv,
    hrv_baseline_7d_ms: round(hrvBase),
    hrv_vs_baseline_pct: hrv && hrvBase ? round((hrv / hrvBase - 1) * 100) : null,
    resting_hr_bpm: rhr,
    resting_hr_baseline_7d_bpm: round(rhrBase),
    resting_hr_vs_baseline_bpm: rhr && rhrBase ? round(rhr - rhrBase) : null,
    sleep_hours: isNum(todayRow.sleepSecs) ? round(todayRow.sleepSecs / 3600) : null,
    sleep_score: isNum(todayRow.sleepScore) ? todayRow.sleepScore : null,
  };

  // --- Load: fitness/fatigue from the latest row that has them, plus 7d vs previous 7d
  const latestLoadRow = [todayRow, ...prior7].find((r) => isNum(r.ctl) && isNum(r.atl)) || {};
  const acts = (activities || []).map((a) => ({
    date: String(a.start_date_local || '').slice(0, 10),
    sport: a.type,
    load: Number(a.icu_training_load) || 0,
  }));
  const inWindow = (a, fromBack, toBack) => a.date >= addDays(today, -toBack) && a.date <= addDays(today, -fromBack);
  const last7 = acts.filter((a) => inWindow(a, 0, 6));
  const prev7 = acts.filter((a) => inWindow(a, 7, 13));
  const sum = (xs) => xs.reduce((s, a) => s + a.load, 0);
  const activeDays = new Set(last7.map((a) => a.date));
  let daysSinceRest = 0;
  while (daysSinceRest < 14 && acts.some((a) => a.date === addDays(today, -daysSinceRest))) daysSinceRest++;
  const load7 = sum(last7);
  const loadPrev7 = sum(prev7);
  const load = {
    ctl: round(latestLoadRow.ctl),
    atl: round(latestLoadRow.atl),
    tsb: latestLoadRow.ctl != null ? round(latestLoadRow.ctl - latestLoadRow.atl) : null,
    load_7d: round(load7, 0),
    load_prev_7d: round(loadPrev7, 0),
    load_change_pct: loadPrev7 > 0 ? round((load7 / loadPrev7 - 1) * 100) : null,
    sessions_7d: last7.length,
    rest_days_7d: 7 - activeDays.size,
    days_since_rest: daysSinceRest,
    trained_today: activeDays.has(today),
  };

  // --- Weather for the target date (Open-Meteo daily block)
  const d = (weather && weather.daily) || {};
  const idx = (d.time || []).indexOf(targetDate);
  const pick = (k) => (idx >= 0 && d[k] ? d[k][idx] : null);
  const weatherOut = {
    temp_min_c: pick('temperature_2m_min'),
    temp_max_c: pick('temperature_2m_max'),
    precip_mm: pick('precipitation_sum'),
    precip_probability_pct: pick('precipitation_probability_max'),
    wind_max_kmh: pick('wind_speed_10m_max'),
    gust_max_kmh: pick('wind_gusts_10m_max'),
  };

  // --- Plan for the target weekday
  const weekday = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'][new Date(targetDate + 'T12:00:00Z').getUTCDay()];
  const planned = (plan && plan.week && plan.week[weekday]) || null;

  // --- Data quality: lets the guardrails act conservatively when data is missing
  const missingToday = Object.entries({ hrv, resting_hr: rhr, sleep_hours: recovery.sleep_hours })
    .filter(([, v]) => v == null)
    .map(([k]) => k);
  const dataQuality = {
    wellness_days_7d: [0, 1, 2, 3, 4, 5, 6].filter((i) => isNum((byDate[addDays(today, -i)] || {}).hrv)).length,
    missing_today: missingToday,
    activities_14d: acts.length, // 0 means "no data", not "fully rested"
    weather_available: idx >= 0,
    plan_available: planned != null,
  };

  return {
    target_date: targetDate,
    weekday,
    data_source: source,
    scenario_id: scenarioId || null,
    goal: plan ? plan.goal : null,
    phase: plan ? plan.phase : null,
    planned,
    recovery,
    load,
    weather: weatherOut,
    data_quality: dataQuality,
  };
}


// --- n8n wrapper
const raw = $('Shape live data').isExecuted
  ? $('Shape live data').first().json
  : $('Shape scenario data').first().json;
const plan = $input.first().json.data;
const context = buildContext({
  targetDate: raw.target_date, source: raw.mode, scenarioId: raw.scenario_id,
  wellness: raw.wellness, activities: raw.activities, weather: raw.weather, plan,
});
const run = {
  workflow_version: raw.workflow_version, n8n_execution_id: raw.n8n_execution_id,
  run_started_at: raw.run_started_at, trigger: raw.trigger, data_source: raw.mode,
  scenario_id: raw.scenario_id, target_date: raw.target_date, guardrails_file: raw.guardrails_file,
};
return [{ json: { run, context } }];

// Loop state travels in the item: run, context, guardrails, and every attempt so far
const g = $input.first().json.data;
const { run, context } = $('Build daily context').first().json;
return [{ json: { run, context, guardrails: g, rules_version: g.version, attempts: [] } }];

// Maker: builds the Claude request and parses the reply.
// The maker knows the guardrail *policy* in plain words but not the thresholds;
// the checker enforces the numbers. Each attempt is a fresh single-turn request
// (previous rejections are quoted in the prompt), so nothing depends on replaying
// earlier model output.

const MAKER_MODEL = 'claude-haiku-5-5';

const SYSTEM_PROMPT = `You plan tomorrow's single training session for an amateur triathlete preparing for an IRONMAN 70.3.

You receive a JSON "daily context": the planned session for tomorrow, recovery signals compared with the athlete's own 7-day baseline, recent training load, tomorrow's weather in Lisbon, and data-quality flags.

How to decide:
- Start from the planned session. Keep it unless the data gives a reason to change it.
- When recovery signals are worse than baseline (lower HRV, higher resting heart rate, short sleep), fatigue is high, load has ramped up quickly, or many days have passed without rest, reduce intensity first, then duration, and choose rest when several signals agree.
- When data is missing, be more conservative, not less.
- Bad weather for an outdoor ride: move it to the indoor trainer rather than skipping it.
- Never make a session longer or harder than planned.
- A rest day has duration 0, intensity "easy" and location "none".

Write "focus" as a short workout description (for example "6 x 3 min at threshold, 2 min easy"). Write "rationale" in at most two sentences, naming the signals that drove the decision. Set "changed_from_plan" to true if sport, duration, intensity or location differs from the plan.

Your proposal is checked by deterministic safety rules before a human approves it. If a previous proposal was rejected, the reasons are listed: fix them without changing anything else.`;

const PROPOSAL_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['sport', 'duration_min', 'intensity', 'location', 'focus', 'changed_from_plan', 'rationale'],
  properties: {
    sport: { type: 'string', enum: ['swim', 'bike', 'run', 'strength', 'rest'] },
    duration_min: { type: 'integer' },
    intensity: { type: 'string', enum: ['easy', 'moderate', 'hard'] },
    location: { type: 'string', enum: ['pool', 'open_water', 'outdoor', 'trainer', 'garage', 'none'] },
    focus: { type: 'string' },
    changed_from_plan: { type: 'boolean' },
    rationale: { type: 'string' },
  },
};

function buildMakerRequest(context, attempts) {
  let user = `Daily context:\n${JSON.stringify(context, null, 1)}`;
  const rejected = attempts.filter((a) => a.verdict && !a.verdict.passed);
  if (rejected.length) {
    user += '\n\nPrevious proposals were rejected by the safety checker:';
    for (const a of rejected) {
      user += `\n- Attempt ${a.attempt}: ${JSON.stringify(a.proposal)}\n  Reasons: ${a.verdict.violations.map((v) => v.message).join('; ')}`;
    }
    user += '\nPropose a corrected session.';
  }
  return {
    model: MAKER_MODEL,
    max_tokens: 4000,
    output_config: { effort: 'low', format: { type: 'json_schema', schema: PROPOSAL_SCHEMA } },
    system: SYSTEM_PROMPT,
    messages: [{ role: 'user', content: user }],
  };
}

// Never throws: an unusable reply becomes proposal=null with a reason,
// which the checker rejects as S0_parse and the loop treats like any rejection.
function parseMakerResponse(resp) {
  const usage = (resp && resp.usage) || {};
  const out = {
    proposal: null,
    stop_reason: resp ? resp.stop_reason : null,
    input_tokens: usage.input_tokens != null ? usage.input_tokens : null,
    output_tokens: usage.output_tokens != null ? usage.output_tokens : null,
    model: resp && resp.model ? resp.model : MAKER_MODEL,
    error: null,
  };
  if (!resp || !Array.isArray(resp.content)) {
    out.error = 'No message in response';
    return out;
  }
  if (resp.stop_reason === 'refusal') {
    out.error = `Refused (${(resp.stop_details && resp.stop_details.category) || 'no category'})`;
    return out;
  }
  if (resp.stop_reason === 'max_tokens') {
    out.error = 'Hit max_tokens before finishing';
    return out;
  }
  const text = resp.content.filter((b) => b.type === 'text').map((b) => b.text).join('');
  try {
    out.proposal = JSON.parse(text);
  } catch (e) {
    out.error = 'Reply was not valid JSON';
  }
  return out;
}


// --- n8n wrapper: one request per attempt; earlier rejections are quoted in the prompt
const s = $input.first().json;
const attempt = s.attempts.length + 1;
return [{ json: {
  ...s,
  attempt,
  call_started_at: new Date().toISOString(),
  call_started_ms: Date.now(),
  request_body: buildMakerRequest(s.context, s.attempts),
} }];

